#include <bits/stdc++.h>using namespace std; int main() {    int t;    cin >> t;    while(t-- > 0){      int n;      cin >> n;      vector<int> a(n);      int sum =0;      bool hasOdd = false;      bool hasEven = false;      for(int i=0; i<n; i++){        cin >> a[i];        if(a[i]%2==0) hasEven = true;        else hasOdd = true;        sum+=a[i];      }      if(sum%2!=0 || (hasOdd && hasEven)){        cout << "YES" << endl;      }      else{        cout << "NO" << endl;      }    }      }